head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[autoComplete > P > disableEdit]<br/>AutoComplete 컴포넌트를 클릭했을 때 편집 모드로 전환하지 않고 아이템 리스트창만 열지 설정합니다.",
    "validation" : [
        "true 설정 시, 컴포넌트의 값이 표시된 영역을 클릭하면 편집 모드로 전환되지 않고 아이템 리스트창이 열립니다.",
        "true 설정 시, 입력창에 검색어를 입력할 수 없으며, 아이템 리스트창에서 아이템을 선택하여 값을 변경합니다.",
        "false 설정 시, editModeEvent 속성에 설정한 시점에 편집 모드로 전환되어 입력창에 검색어를 입력할 수 있습니다.",
        "미설정 시, editModeEvent 속성에 설정한 시점에 편집 모드로 전환되어 입력창에 검색어를 입력할 수 있습니다.",
        "disableEdit='true' 이면 editModeEvent 속성은 무시됩니다.",
    ]
}

// 아이템 (Bu 를 입력하면 Busan, Busanjin 2 건만 검색된다)
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Busanjin", "value" : "BSJ" },
    { "label" : "Jeju", "value" : "CJU" }
];

// stateInfo : 상태 확인 버튼을 누르는 시점의 편집 모드 여부, 리스트창 열림 여부와 아이템, 표시 텍스트, 값
scwin.gVar = { "stateInfo" : "" };



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 아이템 DataList 생성
    scwin.createCityDataList("dlt_city");
    dlt_city.setJSON(scwin.arrCity);

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (disableEdit=true, editModeEvent 미설정)
    con_disableEdit.setValue("2");
    con_editModeEvent.setSelectedIndex(0);

    // 상태 확인 버튼 클릭 시 포커스가 버튼으로 옮겨가 편집 모드가 풀리고 리스트창이 닫히므로 mousedown capture 단계에서 상태를 기록
    btn_getState.render.addEventListener("mousedown", scwin.captureState, true);

    // comp 초기 생성
    scwin.comp_init();
};



scwin.createCityDataList = function (dltID) {
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="' + dltID + '">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof input_prev !== 'undefined') {
        input_prev.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- 아이템(Label / Value) : Seoul / SEL, Seongnam / SNM, Busan / PUS, Busanjin / BSJ, Jeju / CJU\n- 위쪽 input_prev 는 Tab 출발점, 아래쪽 target1 이 AutoComplete\n- 상태 확인을 누르면 포커스가 버튼으로 옮겨가므로 다음 조작은 처음부터 다시 진행\n[절차]\n1. disableEdit, editModeEvent 선택 -> Target 재생성\n2. target1 의 값 표시 영역 클릭 (또는 input_prev 클릭 후 Tab 키) -> 상태 확인\n3. target1 의 값 표시 영역 클릭 (또는 input_prev 클릭 후 Tab 키) -> Bu 입력 -> 상태 확인\n4. target1 의 값 표시 영역 클릭 -> 리스트창의 아이템 클릭 -> 상태 확인\n[확인] 상태 확인의 편집 모드 / 리스트창 열림 / 리스트창 아이템 / 표시 텍스트 / 값"', '', 'label1');

    // Tab 이동 출발점
    await $c.gcm.createBasicInput('', '', 'input_prev');

    // 미설정 옵션은 속성 자체를 넣지 않는다 (createCList 가 빈값 키 제외)
    let properties = {
        disableEdit : con_disableEdit.getText(),
        editModeEvent : con_editModeEvent.getValue(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());
};



// 버튼 mousedown 시점(포커스가 버튼으로 옮겨가기 전)의 상태 기록
//  - 편집 모드 : 값 표시 영역이 숨겨지고 입력창이 표시된 상태
//  - 표시 텍스트 : 편집 모드이면 입력창의 글자, 아니면 값 표시 영역의 글자
scwin.captureState = function (e) {
    let inputElem = document.querySelector("[id='" + target1.id + "_input']");
    let labelElem = document.querySelector("[id='" + target1.id + "_label']");
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");

    let bEditMode = inputElem.offsetWidth > 0 && labelElem.offsetWidth === 0;
    let bListOpen = !!itemTableElem && getComputedStyle(itemTableElem).display !== "none" && getComputedStyle(itemTableElem).visibility !== "hidden";

    let strResult = "편집 모드 : " + bEditMode + " / 리스트창 열림 : " + bListOpen;
    if (bListOpen) {
        let rowElems = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr");
        let arrItem = Array.prototype.filter.call(rowElems, function (row) {
            return row.offsetParent !== null;
        }).map(function (row) {
            return row.textContent;
        });
        strResult += " / 리스트창 아이템 : " + arrItem.join(", ");
    }
    strResult += " / 표시 텍스트 : " + (bEditMode ? inputElem.value : labelElem.textContent) + " / 값 : " + target1.getValue();

    scwin.gVar.stateInfo = strResult;
};



// 클릭 / Tab 포커스 / 입력 / 아이템 선택 후 상태 출력 (validation 1 ~ 5)
scwin.btn_getState_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue(scwin.gVar.stateInfo);
};
